WITH matched_keys AS (SELECT order_id, product_id FROM order_items EXCEPT SELECT order_id, product_id FROM order_items WHERE product_id IS NOT NULL), verified AS (SELECT s.* FROM order_items s INNER JOIN matched_keys k ON s.order_id = k.order_id AND s.product_id = k.product_id) SELECT CASE WHEN unit_price >= 300 THEN 'HIGH' ELSE 'LOW' END AS unit_price_tier, product_id, COUNT(*) AS event_count, COUNT(*) AS num_rows, ROUND(AVG(quantity), 2) AS avg_quantity, PERCENTILE_APPROX(unit_price, ARRAY(0.25, 0.5, 0.75)) AS unit_price_quartiles, ROUND(AVG(quantity), 2) AS avg_quantity_2, APPROX_PERCENTILE(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles FROM verified GROUP BY GROUPING SETS ((CASE WHEN unit_price >= 300 THEN 'HIGH' ELSE 'LOW' END, product_id), (CASE WHEN unit_price >= 300 THEN 'HIGH' ELSE 'LOW' END), ()) ORDER BY avg_quantity_2;
